import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%82%AD%E3%83%BC%E3%83%9C%E3%83%BC%E3%83%89.html","title":"キーボード","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.39,"words":416},"filePathRelative":"キーボード.md"}`),a={name:`キーボード.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="キーボード" tabindex="-1"><a class="header-anchor" href="#キーボード"><span>キーボード</span></a></h1><p><a href="./グッズ関連.html">グッズ関連</a></p><p>おもにBluetoothキーボードのメモ。</p><h2 id="ewijn-bluetoothキーボード-日本語配列" tabindex="-1"><a class="header-anchor" href="#ewijn-bluetoothキーボード-日本語配列"><span>Ewijn Bluetoothキーボード 日本語配列</span></a></h2><p>折りたたまないキーボードを家のソファ用に買った。</p><p><a href="https://link.amazon/B07mnUwC0" target="_blank" rel="noopener noreferrer">amazon: Ewin Bluetoothキーボード</a></p><p>2026-10-15 (木)に1999円で購入。</p><p>なんか型番とか名前が無いんだが、まぁいい。単４電池で日本語配列。19mmピッチ。</p><p>でも<a href="./Supernote.html">Supernote</a>はキーボードの切り替えの設定が無くて日本語配列にならない！まぁ英語配列でもいいか。 なんか微妙にエンターキーを押そうとしてバックスペースを押しちゃうんだが、なんでだろう？MacBookと同じキーピッチに見えるんだが。</p><p>しばらく使って慣れる必要はありそう。とりあえずモモでタイピングするという当初の目標は達成出来そう。</p><p>数字が少し左に寄ってるのでちょこちょこ打ち間違えるな。これは慣れが必要そう。</p><h2 id="iclever折り畳み式ワイヤレスキーボード-ic-bk06" tabindex="-1"><a class="header-anchor" href="#iclever折り畳み式ワイヤレスキーボード-ic-bk06"><span>iClever折り畳み式ワイヤレスキーボード IC-BK06</span></a></h2><p><a href="https://amzn.to/4dsOyrn" target="_blank" rel="noopener noreferrer">amazon: iClever 折りたたみ Bluetooth キーボード IC-BK06</a></p><p>2026-05-19 (火) に購入。4690円。</p><p>キーピッチは19mmとか。</p><p>人間工学がどうとかで少し曲がってる折りたたみキーボード。</p><p>届いたのでRhinocsでこのキーボードを使ってみている。 打ちやすさは割と満足か。数字の6が左手なのが普段の自分と違うが、 他はおおむね問題無さそう。</p><p>マルチペアリングも無事動く。BOOXから書いてみているが、こちらもいい感じだ。 打ちやすさはEWINより上だな。</p><h3 id="しばらく打っての感想、これは予想以上かも" tabindex="-1"><a class="header-anchor" href="#しばらく打っての感想、これは予想以上かも"><span>しばらく打っての感想、これは予想以上かも！？</span></a></h3><p>数字はサイズが小さいので、数字のところの記号はちょくちょく押し間違える。 あと101配列だと思うが、101配列久しぶりだから、というのもある。</p><p>ただ結構長いこと101ユーザーだったので、ある程度は手が覚えているのですぐに慣れそう。 Enter周辺の記号はちょっと狭いけど、まぁまぁ一発で押せているな。このくらいだとキーボードを見なくても順応出来るっぽい。</p><p>右のスペースは少し短いなぁ、と思うが、これは慣れかな。</p><p>まんななかが離れているのは思ったより気にならない。 むしろまんなかのヒンジにひっかかりやすいEWINよりも圧倒的に快適。</p><p>曲ってるのがいいのかは良くわからないが、少なくとも特に打ち間違いとかも無いので問題は感じていない。 Amazonのレビューでは少し慣れがいるという意見も多かったが、自分はそこは最初から違和感なかったな。</p><p>それよりもむしろ久しぶりのSKKに慣れる方が影響はでかい気もしている。</p><p>今の所、文章を打っていて全くストレスを感じていないので、 これはかなりいい買いものだった気がする。</p><p>なんかずっと文章を打っていたい。</p><h2 id="ewin-2つに折りたたみ式キーボード" tabindex="-1"><a class="header-anchor" href="#ewin-2つに折りたたみ式キーボード"><span>EWIN ２つに折りたたみ式キーボード</span></a></h2><p><a href="https://www.amazon.co.jp/dp/B07CZFH6FM" target="_blank" rel="noopener noreferrer">Amazon.co.jp: Ewin Bluetoothキーボード 折りたたみ式</a></p><p>2018年に3880円で買ったキーボードだが、2026年現在でもまだ使えてはいる。</p><p>マルチペアリング対応と書いてあるがなんかやり方は良く分からない。iOS, Android, Windowsのボタンで切り替えできそうだが切り替えられない。どうも無理っぽい。</p><p>最近のはちゃんと切り替えボタンが割り当てられてそうなので新しいのならちゃんと出来るのかなぁ。</p><p>重さは157g、145×99×12mm。なかなかコンパクト。</p><p>Androidボタンとかあるが押しても何が変わったのか全く分からない（キーコードレベルでやってくるものに違いが無い）。マルチペアリングに絡んでそうにも見えるが何を試しても変わらない。うーん。謎。</p><p>打鍵感とか持ち運びやすさとかは結構気に入っている。そこらのノートPCよりは快適。 yの所が折りたたみのヒンジがでっぱっててちょっと押しづらいのでたまに押し損なうが、これは慣れかな。</p><h3 id="ペアリング" tabindex="-1"><a class="header-anchor" href="#ペアリング"><span>ペアリング</span></a></h3><p>左上のconnectのボタンを長押しすると青いランプが点灯して、その状態でスマホ側で新規デバイス接続的なのをやると見える。</p><h3 id="androidでのかな漢字変換切り替え" tabindex="-1"><a class="header-anchor" href="#androidでのかな漢字変換切り替え"><span>Androidでのかな漢字変換切り替え</span></a></h3><p>Command+Spaceでオンオフ出来る。</p><h3 id="androidで刻印と違うキーが出力される場合の設定" tabindex="-1"><a class="header-anchor" href="#androidで刻印と違うキーが出力される場合の設定"><span>Androidで刻印と違うキーが出力される場合の設定</span></a></h3><p>デフォルトだと刻印とは違うキーが来るが、設定＞接続済みのデバイス＞Bluetooth 3.0 Keyboard＞キーボードの設定を選び、 さらにGBoardの「日本語（12キー)」と書いてある所をタップして「物理キーボードのレイアウト」が「日本語109A」になっているのを「英語（米国）」に変えると刻印通りとなった。</p><p>なぜGBoardの設定がViewに来るキーコードに影響を与えるのかはわからんが、なんかプライマリーのIMEが影響しているのかなぁ。</p>`,42)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};